 343	 loadCart(): void {
 344	 this.cartService.getCart().subscribe({
 345	 next: (cart) => {
 346	 this.cart = cart
 347	 this.loading = false
 348	 },
 349	 error: (error) => {
 350	 console.error("Error loading cart:", error)
 351	 this.loading = false
 352	 },
 353	 })
 354	 }
 355	
 356	 updateQuantity(item: CartItem, newQuantity: number): void {
 357	 if (newQuantity <= 0) {
 358	 this.removeItem(item)
 359	 return
 360	 }
 361	
 362	 this.cartService.updateItemQuantity(item.id, newQuantity).subscribe({
 363	 next: (cart) => {
 364	 this.cart = cart
 365	 },
 366	 error: (error: any) => {
 367	 let errorMessage = 'Failed to update quantity.';
 368	 if (error.status === 400 && error.error?.message) {
 369	 errorMessage = error.error.message;
 370	 }
 371	 console.error("Error updating quantity:", error)
 372	 },
 373	 })
 374	 }
 375	
