 24	 @ExceptionHandler(ResourceNotFoundException.class)
 25	 public ResponseEntity<Map<String, Object>> handleResourceNotFound(ResourceNotFoundException ex, WebRequest request) {
 26	 Map<String, Object> error = new HashMap<>();
 27	 error.put("timestamp", LocalDateTime.now());
 28	 error.put("status", HttpStatus.NOT_FOUND.value());
 29	 error.put("error", "Not Found");
 30	 error.put("message", ex.getMessage());
